insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9752, 36, 'Allgemeine Strategie und Kooperation zur Stärkung von Innenstädten und Einzelhandel ohne konkretes Instrument (Land)', 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'offen', null, 'land', null, true, 'blind'),
  (9753, 36, 'Leerstandserfassung und Leerstandsmonitoring für Gewerbeflächen (Land)', 'Ein Kataster schafft Transparenz und erleichtert Vermittlung an Nutzer; es ändert aber weder Nachfrage noch Mieten und wirkt nur zusammen mit weiteren Instrumenten.', 'offen', null, 'land', null, true, 'blind'),
  (9754, 36, 'Zwischennutzung leerstehender Flächen fördern und Genehmigungen dafür erleichtern (Land)', 'Zwischennutzungen beleben leere Läden kurzfristig und mit wenig Risiko; sie sind befristet, oft ohne Handel, und ob sie zu dauerhafter Vermietung führen, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9755, 36, 'Förderprogramm zum Umbau von Handelsimmobilien für gemischte Nutzungen (Land)', 'Dauerhafte Mischnutzung (Kultur, Bildung, Gründer, Dienste) bringt Besuchsanlässe in Zentren zurück; Wirkung auf den verbleibenden Handel ist kaum belegt, Umbau ist teuer und dauert.', 'offen', null, 'land', null, true, 'blind'),
  (9756, 36, 'Kommunaler Erwerb leerstehender Gewerbeimmobilien, auch über Vorkaufsrechte (Land)', 'Öffentliches Eigentum erlaubt gezielte Belegung leerer Flächen; Erwerb ist teuer, Vorkaufsrechte sind rechtlich eng, und Gemeinwohlnutzungen schaffen nicht unbedingt Einkaufsangebote.', 'offen', null, 'land', null, true, 'blind'),
  (9757, 36, 'Bundesmittel für kommunalen Erwerb leerstehender Gewerbeimmobilien für Gemeinwohlnutzungen (Bund)', 'Ein Fonds kann Kommunen den Zugriff auf Leerstand ermöglichen; Kultur- oder Sorgenutzungen beleben Zentren, schaffen aber kaum Einkaufsangebote, Wirkung kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (9758, 36, 'Pflichten, Fristen und Abgaben gegen langfristigen Gewerbeleerstand (Land)', 'Erfahrungen mit der französischen Leerstandsabgabe: in gefragten Lagen bringt sie Eigentümer zum Gespräch, in schwachen Lagen kaum Wirkung. Landesrechtliche Grundlage und Eigentumsschutz sind ungeklärt.', 'gemischt', 'https://www.banquedesterritoires.fr/taxe-sur-les-friches-commerciales-un-outil-utiliser-bon-escient', 'land', null, true, 'blind'),
  (9759, 36, 'Mehr verkaufsoffene Sonntage und längere Ladenöffnung im verfassungsrechtlichen Rahmen (Land)', 'Studien zur Freigabe der Sonntagsöffnung in Europa zeigen mehr Beschäftigung und Ausgaben; wenige zusätzliche Sonntage wirken vor allem als Ereignis. Sonntagsöffnungen brauchen einen Anlass und werden oft gerichtlich gekippt.', 'gemischt', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'land', null, true, 'blind'),
  (9760, 36, 'Vollständige Freigabe der Ladenöffnung an Sonn- und Feiertagen (Land)', 'Freigabe der Sonntagsöffnung brachte in Europa mehr Beschäftigung und Ausgaben, kleine Geschäfte profitieren aber weniger. Der Sonntagsschutz (Art. 140 GG, Art. 139 WRV) verbietet laut BVerfG eine generelle Freigabe.', 'gemischt', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'land', null, true, 'blind'),
  (9761, 36, 'Autoerreichbarkeit von Geschäftsstraßen sichern: Ladezonen, Kurzzeitparken, keine Durchfahrtssperren (Land)', 'Nach einer Studie zu Madrid sanken Ladenausgaben Auswärtiger nach Zufahrtsbeschränkungen; andere Studien finden Vorteile von Verkehrsberuhigung. Kurzzeitparken und Lieferzonen sind lokal leicht umsetzbar.', 'gemischt', 'https://www.iese.edu/insight/articles/low-emission-zones-business-commerce/', 'land', null, true, 'blind'),
  (9762, 36, 'Fahrspuren und Parkraum in Innenstädten erhalten, keine Fahrverbote (Bund)', 'Autoerreichbarkeit kann Besuche aus dem Umland sichern (Madrid-Studie), Fußgängerzonen zeigen aber oft mehr Umsatz. Parkraum regeln die Kommunen; der Bund kann nur über StVO und Förderung beitragen.', 'gemischt', 'https://www.iese.edu/insight/articles/low-emission-zones-business-commerce/', 'bund', null, true, 'blind'),
  (9763, 36, 'Verkehrsberuhigung und Umverteilung des Straßenraums zugunsten Fuß-, Radverkehr und Aufenthalt in Zentren (Land)', 'Übersichten aus Deutschland und Großbritannien zeigen meist mehr Passanten und Umsatz in beruhigten Zonen, mit Einbußen in der Übergangszeit und am Rand; Zufahrtsbeschränkungen können Kunden aus dem Umland verdrängen.', 'gemischt', 'https://trid.trb.org/View/408042', 'land', null, true, 'blind'),
  (9764, 36, 'Park-and-Ride am Stadtrand mit Nahverkehr in die Zentren (Land)', 'Erleichtert Besuchern aus dem Umland die Anreise und entlastet die Innenstadt; Park-and-Ride deckt seine Kosten meist nicht, ein kostenloses Ticket erhöht den Zuschussbedarf, die Wirkung auf den Handel ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9765, 36, 'Bauliche Aufwertung und Umgestaltung öffentlicher Räume in Zentren (Land)', 'Fallstudien zeigen nach Aufwertungen mehr Aufenthalt und höhere Ladenmieten; kausale Studien sind selten, höhere Mieten können kleine Geschäfte belasten. Umsetzung über Kommunen und Förderung in mehreren Jahren.', 'gemischt', null, 'land', null, true, 'blind'),
  (9766, 36, 'Städtebauförderung für Zentren ausbauen oder eigenes Landesprogramm auflegen (Land)', 'Zentrenprogramme finanzieren Aufwertung, Geschäftsstraßenmanagement und Leerstandsprojekte, Begleitforschung berichtet verbesserte Perspektiven; kausale Wirkungen sind methodisch kaum nachweisbar. Ausbau hängt teils vom Bund ab.', 'gemischt', 'https://repos.hcu-hamburg.de/handle/hcu/503', 'land', null, true, 'blind'),
  (9767, 36, 'Mittel der Städtebauförderung für Innenstädte und Ortszentren aufstocken (Bund)', 'Der Bund finanziert die Städtebauförderung bereits und kann sie aufstocken; Programme wie Lebendige Zentren stärken Aufwertung und Nutzungsmischung, ihre kausale Wirkung ist aber methodisch kaum nachweisbar.', 'gemischt', 'https://repos.hcu-hamburg.de/handle/hcu/503', 'bund', null, true, 'blind'),
  (9768, 36, 'Gewerbemieter vor Verdrängung schützen über Bundesrat oder Bundesrecht (Land)', 'Mietbegrenzung oder Milieuschutz für Gewerbe kann kleine Läden in teuren Lagen halten; Schließungen haben aber meist andere Gründe, Datenbasis und Folgen sind ungeklärt. Das Land braucht eine Bundesmehrheit.', 'offen', null, 'land', null, true, 'blind'),
  (9769, 36, 'Betriebsnachfolge im lokalen Handel erleichtern: Nachfolgekredite und einfachere Genehmigungen (Land)', 'Erleichterte Übernahmen können einzelne Schließungen verhindern; fehlende Nachfolge ist aber nur ein Grund für Leerstand neben Nachfrage und Onlinehandel, die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9770, 36, 'Einzelhandelssteuerung zugunsten der Zentren, keine neuen Einkaufszentren außerhalb (Land)', 'In Großbritannien lenkten Bauhürden für Großflächen am Stadtrand Ketten in die Zentren, schwächten dort aber unabhängige Läden. Landes- und Regionalplanung kann steuern, ein pauschales Verbot ist rechtlich angreifbar.', 'gemischt', 'https://nber.org/papers/w19797', 'land', null, true, 'blind'),
  (9771, 36, 'Gleiche Regeln für Online-Plattformen aus Drittstaaten bei Zoll, Steuern und Produktverantwortung (Bund)', 'Gleiche Zoll- und Haftungsregeln mindern einen Kostenvorteil billiger Importe; der Onlinehandel insgesamt bleibt davon unberührt. Zoll und Produktrecht entscheidet die EU (Abschaffung der 150-Euro-Grenze läuft).', 'offen', null, 'bund', null, true, 'blind')
