  (36, 16, 'MV', 'keine', 'Inhaltsverzeichnis (S. 3), Kapitel 5 Wirtschaft (S. 9–10), 12 Verkehr (S. 20–21), 16 Kommunen und Landesentwicklung (S. 25–26) sowie Fundstellen S. 23, 24 gelesen; einzige Innenstadt-Stelle (S. 26) ist ein allgemeines Ziel ohne Instrument, nichts Konkretes zu Sortiment/Ansiedlung, Aufenthaltsqualität, Erreichbarkeit oder Öffnungszeiten in Innenstädten.', '2026-10-08', true, '{3602,3603,3604}'),
  (36, 16, 'ST', 'massnahmen', null, '2026-10-08', true, '{3602,3603,3604}'),
  (36, 17, null, 'keine', 'Inhaltsverzeichnis/Präambel (S. 2–3), Kapitel Wirtschaft/Mittelstand und Infrastruktur (S. 14–16), Landwirtschaft (S. 19–20), Wohnen (S. 28), Verkehr und Verbraucherschutz (S. 30–31), Digitalisierung (S. 42–43) sowie Fundstellen S. 11 und 19 gelesen; keine konkrete Zusage zu Innenstadt, Ortskern, Einzelhandel oder Leerstand von Geschäften.', '2026-10-08', true, '{3601,3602,3603,3604}'),
  (36, 17, 'BE', 'keine', 'Kein Inhaltsverzeichnis; Verkehr (S. 48–50), Natur/Umwelt/Sauberkeit (S. 56–58), Innere Sicherheit (S. 38–41), Energie (S. 47), Wohnen/Leerstand (S. 8, 12), Finanzen (S. 54) und alle Fundstellen gelesen. Einzelhandel, Geschäfte, Ortskerne kommen nicht vor; Sauberkeits- und Verkehrszusagen gelten stadtweit ohne Innenstadtbezug (R2); S. 47 (''Innenstadtbereich'') ist keine Handlungszusage.', '2026-10-08', true, '{3602,3603,3604}'),
