  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9772, 36, 11, null, 'Lehnt Fahrverbote für Innenstädte und das Umwidmen von Parkplätzen ab; die Innenstadt soll mit dem Auto erreichbar bleiben.', '{3604}', 9762, 1, 2, null, 'Autoerreichbarkeit kann Besuche aus dem Umland sichern (Madrid-Studie), Fußgängerzonen zeigen aber oft mehr Umsatz. Parkraum regeln die Kommunen; der Bund kann nur über StVO und Förderung beitragen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', 'https://www.iese.edu/insight/articles/low-emission-zones-business-commerce/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9773, 36, 11, 'BE', 'Acht verkaufsoffene Sonntage tatsächlich ermöglichen, rechtssichere Sonntagsöffnung; Bezirke dürfen zweimal im Jahr zusätzliche verkaufsoffene Sonntage festlegen', '{3604}', 9759, 1, 2, null, 'Studien zur Freigabe der Sonntagsöffnung in Europa zeigen mehr Beschäftigung und Ausgaben; wenige zusätzliche Sonntage wirken vor allem als Ereignis. Sonntagsöffnungen brauchen einen Anlass und werden oft gerichtlich gekippt.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9774, 36, 11, 'BE', 'Landesstrategie zur Stärkung des Einzelhandels und gemeinsam mit Bezirken, Handel und Gastronomie Kiezpläne für jede Einkaufsstraße', '{3602}', 9752, 1, 3, null, 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9775, 36, 11, 'BE', 'Städtebauförderprogramm „Lebendige Zentren“ gemeinsam mit dem Bund um- und ausbauen', '{3602,3603}', 9766, 2, 2, null, 'Zentrenprogramme finanzieren Aufwertung, Geschäftsstraßenmanagement und Leerstandsprojekte, Begleitforschung berichtet verbesserte Perspektiven; kausale Wirkungen sind methodisch kaum nachweisbar. Ausbau hängt teils vom Bund ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://repos.hcu-hamburg.de/handle/hcu/503', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9776, 36, 11, 'BE', 'Förderprogramm für den Umbau von Handelsimmobilien zu Wohn-, Büro- und Kulturnutzungen', '{3602}', 9755, 2, 2, null, 'Dauerhafte Mischnutzung (Kultur, Bildung, Gründer, Dienste) bringt Besuchsanlässe in Zentren zurück; Wirkung auf den verbleibenden Handel ist kaum belegt, Umbau ist teuer und dauert.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9777, 36, 11, 'BE', 'Leerstand bekämpfen: Zentrengipfel mit den Bezirken fortführen und systematisches Leerstandsmonitoring für Büro- und Gewerbeflächen einführen', '{3602}', 9753, 1, 3, null, 'Ein Kataster schafft Transparenz und erleichtert Vermittlung an Nutzer; es ändert aber weder Nachfrage noch Mieten und wirkt nur zusammen mit weiteren Instrumenten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9778, 36, 11, 'BE', 'Leerstehende landeseigene Immobilien über eine zentrale Vergabestelle erfassen und flexibel, auch temporär (z. B. Pop-up), an Start-ups und Kreativwirtschaft vergeben', '{3602}', 9754, 1, 3, null, 'Zwischennutzungen beleben leere Läden kurzfristig und mit wenig Risiko; sie sind befristet, oft ohne Handel, und ob sie zu dauerhafter Vermietung führen, ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9779, 36, 11, 'BE', 'Keine Durchfahrtssperren wie Poller, damit Einzelhandel für Kunden und Lieferanten erreichbar bleibt; einheitlicher Baukasten für Verkehrsberuhigung für die Bezirke', '{3604}', 9761, 1, 3, null, 'Nach einer Studie zu Madrid sanken Ladenausgaben Auswärtiger nach Zufahrtsbeschränkungen; andere Studien finden Vorteile von Verkehrsberuhigung. Kurzzeitparken und Lieferzonen sind lokal leicht umsetzbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=70', 'https://www.iese.edu/insight/articles/low-emission-zones-business-commerce/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9780, 36, 11, 'MV', 'Mehr Polizeipräsenz in den Innenstädten und an Kriminalitätsschwerpunkten, höherer Kontrolldruck, wirksamere Platzverweise und Aufenthaltsverbote', '{3603}', null, 2, 2, null, 'Gezielte Polizeipräsenz an Kriminalitätsschwerpunkten senkt Kriminalität nachweislich ohne Verdrängung; ob sich das in mehr Besuchen der Innenstadt zeigt, ist kaum untersucht. Zusätzliches Personal fehlt vielerorts.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356500/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9781, 36, 11, 'MV', 'Regeln für verkaufsoffene Sonntage praxisnah und flexibler gestalten, nach Vorbild liberalerer Nachbarländer, für Einzelhandel, Gastronomie und Tourismus', '{3604}', 9759, 1, 2, null, 'Studien zur Freigabe der Sonntagsöffnung in Europa zeigen mehr Beschäftigung und Ausgaben; wenige zusätzliche Sonntage wirken vor allem als Ereignis. Sonntagsöffnungen brauchen einen Anlass und werden oft gerichtlich gekippt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=23', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9782, 36, 11, 'MV', 'Entwicklungsinstrumente gezielt nutzen, um Dorfkerne sowie Gewerbe- und Industrieflächen zu stärken', '{3602}', 9752, 1, 3, null, 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=122', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9783, 36, 11, 'ST', 'Stadtkerne stärken durch gezielte Unterstützung des Einzelhandels und kreative Konzepte gegen Leerstand', '{3602}', 9752, 1, 3, null, 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=66', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9784, 36, 11, 'ST', 'Umweltzonen in Innenstädten aufheben', '{3604}', null, 1, 2, null, 'Zufahrtsbeschränkungen können Ladenbesuche Auswärtiger senken (Madrid-Studie); heutige Umweltzonen schließen aber kaum noch Fahrzeuge aus. Aufhebung setzt Einhaltung der EU-Grenzwerte voraus.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', 'https://www.iese.edu/insight/articles/low-emission-zones-business-commerce/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9785, 36, 12, null, 'Städtebauförderung ausbauen und den stationären Einzelhandel stärken (im Rahmen der Stärkung ländlicher Räume und kleiner Städte)', '{3602,3603}', 9767, 2, 3, null, 'Der Bund finanziert die Städtebauförderung bereits und kann sie aufstocken; Programme wie Lebendige Zentren stärken Aufwertung und Nutzungsmischung, ihre kausale Wirkung ist aber methodisch kaum nachweisbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=52', 'https://repos.hcu-hamburg.de/handle/hcu/503', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9786, 36, 12, null, 'Leerstand-Strategie für den ländlichen Raum: Förderprogramme und Anreize, damit Kommunen und Eigentümer leerstehende Immobilien in Wohn- oder Gewerberaum umwandeln', '{3602}', null, 1, 2, null, 'Förderung der Umnutzung leerer Gebäude kann Ortskerne beleben; Wohnnutzung schafft aber keine Einkaufsangebote, und ohne Mittelangabe und Ortskernbezug bleibt die Wirkung auf den Handel gering.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=53', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9787, 36, 12, 'BE', 'Empfehlungen des Berliner Zentrengipfels umsetzen, um Einkaufsstraßen attraktiver zu machen, und lokale Selbstorganisation stärken', '{3602}', 9752, 1, 3, null, 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=13', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9788, 36, 12, 'BE', 'Standortgemeinschaften (BIDs) in allen Bezirken ermöglichen und Bezirke beim Aufbau von Managementteams für überregional bedeutende Standorte unterstützen', '{3602}', null, 1, 3, null, 'Standortgemeinschaften bündeln Geld der Eigentümer für Pflege und Marketing; Studien finden keine (New York) oder nur vorübergehende Umsatzeffekte (Schweden). Rechtlich und organisatorisch gut umsetzbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=13', 'https://socialsciences.uchicago.edu/node/23348', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9789, 36, 12, 'BE', 'Leerstehende Shoppingcenter und Ladenzeilen mit Jugend-, Kultur-, Sport- und sozialen Angeboten neu beleben, Zwischennutzungen fördern und Genehmigungen vereinfachen', '{3602}', 9754, 1, 3, null, 'Zwischennutzungen beleben leere Läden kurzfristig und mit wenig Risiko; sie sind befristet, oft ohne Handel, und ob sie zu dauerhafter Vermietung führen, ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=19', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9790, 36, 12, 'BE', 'Mehr Ladezonen und Kurzzeitparkplätze in Geschäftsstraßen einrichten', '{3604}', 9761, 1, 3, null, 'Nach einer Studie zu Madrid sanken Ladenausgaben Auswärtiger nach Zufahrtsbeschränkungen; andere Studien finden Vorteile von Verkehrsberuhigung. Kurzzeitparken und Lieferzonen sind lokal leicht umsetzbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=27', 'https://www.iese.edu/insight/articles/low-emission-zones-business-commerce/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9791, 36, 12, 'MV', 'Landesprogramm „Neue Dorfmitte“ weiterentwickeln mit dem Ziel eines Dorfladens für den täglichen Bedarf in erreichbarer Nähe jeder Gemeinde, lebendige Dorfmitten', '{3602}', null, 2, 3, null, 'Geförderte Dorfläden schaffen direkt Einkaufsangebote in Ortsmitten und sind als Treffpunkt beliebt; viele tragen sich nur mit regionalem Sortiment und Bürgerbeteiligung, belastbare Wirkungsstudien fehlen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=19', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9792, 36, 12, 'MV', 'Kooperation von Kultur und Tourismus stärken, um Innenstädte mit Kulturrouten, Festivals und Kunst im öffentlichen Raum zu beleben', '{3603}', null, 1, 3, null, 'Festivals, Kulturrouten und Kunst im öffentlichen Raum schaffen Besuchsanlässe; die Wirkung ist meist punktuell und auf dauerhafte Einkaufsangebote kaum untersucht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=80', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9793, 36, 12, 'ST', 'Stadt- und Ortszentren durch gemeinsame Initiativen von Kommunen und Wirtschaft stärken', '{3602}', 9752, 1, 3, null, 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=6', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9794, 36, 13, null, 'Sich dafür einsetzen, dass große Onlineplattformen wie lokale Läden Produktverantwortung übernehmen müssen; Digital Fairness Act der EU unterstützen', '{3601}', 9771, 1, 1, null, 'Gleiche Zoll- und Haftungsregeln mindern einen Kostenvorteil billiger Importe; der Onlinehandel insgesamt bleibt davon unberührt. Zoll und Produktrecht entscheidet die EU (Abschaffung der 150-Euro-Grenze läuft).', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9795, 36, 13, null, 'Mittel der Städtebauförderung aufstocken und Innenentwicklung vereinfachen, für lebendige, nutzungsgemischte Innenstädte und Ortszentren', '{3602,3603}', 9767, 2, 3, null, 'Der Bund finanziert die Städtebauförderung bereits und kann sie aufstocken; Programme wie Lebendige Zentren stärken Aufwertung und Nutzungsmischung, ihre kausale Wirkung ist aber methodisch kaum nachweisbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', 'https://repos.hcu-hamburg.de/handle/hcu/503', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9796, 36, 13, null, 'Geschäfte und Gastronomie im Gewerbemietrecht vor Verdrängung schützen', '{3602}', null, 1, 2, null, 'Mehr Schutz im Gewerbemietrecht kann kleine Geschäfte in teuren Lagen halten; Schließungen haben oft andere Gründe, Folgen für Angebot und Investitionen sind ungeklärt. Der Bund ist zuständig, die Ausgestaltung umstritten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=105', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9797, 36, 13, null, 'Rahmenbedingungen für Kulturorte, Clubs und Livemusikstätten vor allem in Innenstädten über Lärmschutz, Baurecht und Gewerbemietrecht verbessern', '{3602}', null, 1, 2, null, 'Bessere Bedingungen für Clubs und Kulturorte stärken die Nutzungsmischung in Innenstädten; Einkaufsangebote betrifft das kaum, Wirkung wenig untersucht. Lärmschutz- und Baurechtsänderungen sind möglich, aber konfliktreich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=124', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9798, 36, 13, 'BE', 'Einkaufszentren zu multifunktionalen Orten mit Kultur, Bildung, Gesundheit und Verwaltung weiterentwickeln; Mischnutzung, flexible Mietmodelle und Zwischennutzung gegen Leerstand fördern', '{3602}', 9755, 2, 2, null, 'Dauerhafte Mischnutzung (Kultur, Bildung, Gründer, Dienste) bringt Besuchsanlässe in Zentren zurück; Wirkung auf den verbleibenden Handel ist kaum belegt, Umbau ist teuer und dauert.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=101', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9799, 36, 13, 'BE', 'Gesetzlichen Rahmen für verkaufsoffene Sonntage ausschöpfen, unter Schutz der Beschäftigten im Einzelhandel', '{3604}', 9759, 1, 2, null, 'Studien zur Freigabe der Sonntagsöffnung in Europa zeigen mehr Beschäftigung und Ausgaben; wenige zusätzliche Sonntage wirken vor allem als Ereignis. Sonntagsöffnungen brauchen einen Anlass und werden oft gerichtlich gekippt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=102', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9800, 36, 13, 'BE', 'Milieuschutz auch für Gewerbemieter einführen, um Betriebe wie den Einzelhandel vor Verdrängung zu schützen', '{3602}', 9768, 1, 1, null, 'Mietbegrenzung oder Milieuschutz für Gewerbe kann kleine Läden in teuren Lagen halten; Schließungen haben aber meist andere Gründe, Datenbasis und Folgen sind ungeklärt. Das Land braucht eine Bundesmehrheit.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=101', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9801, 36, 13, 'BE', 'Bezahlbare landeseigene Gewerbeflächen im Sinne der Nutzungsmischung schaffen, für Betriebe vom Handwerk über den Einzelhandel bis zur Industrie', '{3602}', null, 1, 2, null, 'Bezahlbare landeseigene Gewerbeflächen können Mischung und kleine Betriebe sichern; sie sind nicht auf Zentren und Handel beschränkt, Flächen und Mittel sind begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=101', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9802, 36, 13, 'MV', 'Leerstand aktiv managen: kommunales Leerstands- und Brachflächenmanagement und Förderung temporärer Zwischennutzungen (im Kapitel Wohnraum)', '{3602}', 9754, 1, 3, null, 'Zwischennutzungen beleben leere Läden kurzfristig und mit wenig Risiko; sie sind befristet, oft ohne Handel, und ob sie zu dauerhafter Vermietung führen, ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=52', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9803, 36, 13, 'ST', 'Kommunen beim Abbau von Leerstand unterstützen und Zwischennutzungen ermöglichen, etwa durch Start-ups, Pop-up-Stores oder nichtkommerzielle Treffpunkte', '{3602}', 9754, 1, 3, null, 'Zwischennutzungen beleben leere Läden kurzfristig und mit wenig Risiko; sie sind befristet, oft ohne Handel, und ob sie zu dauerhafter Vermietung führen, ist kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=93', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9804, 36, 13, 'ST', 'Ortskerne durch Handel und Dienstleistungen stärken statt neue Flächen auf der grünen Wiese zu versiegeln', '{3602}', 9770, 2, 2, null, 'In Großbritannien lenkten Bauhürden für Großflächen am Stadtrand Ketten in die Zentren, schwächten dort aber unabhängige Läden. Landes- und Regionalplanung kann steuern, ein pauschales Verbot ist rechtlich angreifbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=93', 'https://nber.org/papers/w19797', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9805, 36, 13, 'ST', 'Kommunen erhalten abgestufte Instrumente gegen langfristigen Leerstand: Nutzungs- oder Sanierungsfristen, höhere Abgaben, verpflichtende Zwischennutzung; Übernahme als letztes Mittel', '{3602}', 9758, 1, 1, null, 'Erfahrungen mit der französischen Leerstandsabgabe: in gefragten Lagen bringt sie Eigentümer zum Gespräch, in schwachen Lagen kaum Wirkung. Landesrechtliche Grundlage und Eigentumsschutz sind ungeklärt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=98', 'https://www.banquedesterritoires.fr/taxe-sur-les-friches-commerciales-un-outil-utiliser-bon-escient', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9806, 36, 14, null, 'Regeln auf europäischer und nationaler Ebene, damit importierte Waren auf großen Online-Plattformen angemessen verzollt und versteuert werden', '{3601}', 9771, 1, 1, null, 'Gleiche Zoll- und Haftungsregeln mindern einen Kostenvorteil billiger Importe; der Onlinehandel insgesamt bleibt davon unberührt. Zoll und Produktrecht entscheidet die EU (Abschaffung der 150-Euro-Grenze läuft).', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=16', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9807, 36, 14, 'BE', 'Bauliche Umgestaltung von Vierteln mit viel Einzelhandel, um Aufenthaltsqualität, Sauberkeit und Sicherheit zu erhöhen', '{3603}', 9765, 2, 2, null, 'Fallstudien zeigen nach Aufwertungen mehr Aufenthalt und höhere Ladenmieten; kausale Studien sind selten, höhere Mieten können kleine Geschäfte belasten. Umsetzung über Kommunen und Förderung in mehreren Jahren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=28', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9808, 36, 14, 'BE', 'Sondernutzungsflächen für Einzelhandel und Gastronomie unbürokratisch ausweisen; berlinweit einheitliche, digitale Genehmigungsstandards mit Fristen für Warenauslagen und Außengastronomie', '{3603}', null, 1, 3, null, 'Einfachere Genehmigungen für Außengastronomie und Warenauslagen beleben Straßen und sind schnell umsetzbar; der Beitrag zu Angebot und Leerstand ist klein und kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=28', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9809, 36, 14, 'BE', 'Sonntagsöffnung auf Bundesebene ganz freigeben; zunächst sollen die Bezirke zusätzliche verkaufsoffene Sonntage selbst genehmigen und terminieren dürfen', '{3604}', 9760, 2, 0, null, 'Freigabe der Sonntagsöffnung brachte in Europa mehr Beschäftigung und Ausgaben, kleine Geschäfte profitieren aber weniger. Der Sonntagsschutz (Art. 140 GG, Art. 139 WRV) verbietet laut BVerfG eine generelle Freigabe.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=21', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9810, 36, 14, 'BE', 'Leer stehende Gewerbe-, Büro- und Ladenflächen dürfen freiwillig in Wohnraum umgewandelt werden', '{3602}', null, 1, 3, null, 'Freiwillige Umwandlung leerer Läden in Wohnungen füllt Leerstand und bringt Bewohner ins Zentrum; Einkaufsflächen gehen verloren. Über die Landesbauordnung leicht umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=46', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9811, 36, 14, 'BE', 'Zwischennutzungen leer stehender Gebäude und temporäre Veranstaltungsflächen für Kultur erleichtern', '{3602}', 9754, 1, 3, null, 'Zwischennutzungen beleben leere Läden kurzfristig und mit wenig Risiko; sie sind befristet, oft ohne Handel, und ob sie zu dauerhafter Vermietung führen, ist kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9812, 36, 14, 'MV', 'Das Verbot der Ladenöffnung an Sonntagen vollständig aufheben (im Kapitel Tourismus).', '{3604}', 9760, 2, 0, null, 'Freigabe der Sonntagsöffnung brachte in Europa mehr Beschäftigung und Ausgaben, kleine Geschäfte profitieren aber weniger. Der Sonntagsschutz (Art. 140 GG, Art. 139 WRV) verbietet laut BVerfG eine generelle Freigabe.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=19', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9813, 36, 14, 'ST', 'Ladenöffnungszeitengesetz vollständig liberalisieren, mit größtmöglicher Ausweitung der Sonntagsöffnungen und Öffnungen an Feiertagen', '{3604}', 9760, 2, 0, null, 'Freigabe der Sonntagsöffnung brachte in Europa mehr Beschäftigung und Ausgaben, kleine Geschäfte profitieren aber weniger. Der Sonntagsschutz (Art. 140 GG, Art. 139 WRV) verbietet laut BVerfG eine generelle Freigabe.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=7', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9814, 36, 14, 'ST', 'Radinfrastruktur ausbauen, mit sicheren Fahrrad-Abstellanlagen und Ladepunkten unter anderem in Ortszentren', '{3604}', null, 1, 3, null, 'Sichere Radabstellanlagen in Ortszentren erleichtern das Einkaufen mit dem Rad und sind günstig umsetzbar; ihr Beitrag zur Belebung der Zentren ist begrenzt und wenig untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=66', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9815, 36, 15, null, 'Innerstädtische Fahrspuren und Parkraum erhalten und ausbauen, auch um die Attraktivität des Einzelhandels zu schützen', '{3604}', 9762, 1, 2, null, 'Autoerreichbarkeit kann Besuche aus dem Umland sichern (Madrid-Studie), Fußgängerzonen zeigen aber oft mehr Umsatz. Parkraum regeln die Kommunen; der Bund kann nur über StVO und Förderung beitragen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=43', 'https://www.iese.edu/insight/articles/low-emission-zones-business-commerce/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9816, 36, 15, null, 'Das Bild historischer Innenstädte bewahren und bei Bedarf durch Rekonstruktionen wiederherstellen', '{3603}', null, 1, 2, null, 'Ein gepflegtes historisches Stadtbild kann Aufenthalt und Besuche fördern; Rekonstruktionen sind teuer, langwierig und zum Handel kaum untersucht. Denkmalpflege liegt bei Ländern und Kommunen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=172', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9817, 36, 15, 'MV', 'Ladenschlusszeiten und Bäderverkaufsverordnung liberalisieren, mehr verkaufsoffene Sonntage und mehr touristische Orte mit Sonderöffnung', '{3604}', 9759, 1, 2, null, 'Studien zur Freigabe der Sonntagsöffnung in Europa zeigen mehr Beschäftigung und Ausgaben; wenige zusätzliche Sonntage wirken vor allem als Ereignis. Sonntagsöffnungen brauchen einen Anlass und werden oft gerichtlich gekippt.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=13', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9818, 36, 15, 'MV', 'Bei öffentlichen Bauten, die Innenstädte prägen, künftig auf einen regionalen architektonischen Heimatstil achten', '{3603}', null, 1, 3, null, 'Die Gestaltung öffentlicher Bauten prägt das Stadtbild nur am Rand; ein bestimmter Baustil berührt Angebot und Aufenthalt in Innenstädten kaum, die Wirkung ist nicht untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=89', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9819, 36, 15, 'ST', 'Kredite zu Sonderkonditionen für die Sanierung der Altbausubstanz in historischen Innenstadtbereichen ermöglichen', '{3603}', null, 1, 3, null, 'Günstige Kredite für die Sanierung historischer Altbauten können das Stadtbild aufwerten und sind über die Förderbank umsetzbar; der Bezug zu Handel und Aufenthalt bleibt mittelbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=58', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9820, 36, 15, 'ST', 'Ortsumfahrungen schneller realisieren, um die Ortskerne vom Durchgangsverkehr zu entlasten', '{3603}', null, 1, 2, null, 'Ortsumfahrungen nehmen Durchgangsverkehr aus Ortskernen und verbessern den Aufenthalt; zugleich fällt Laufkundschaft weg. Planung und Bau dauern meist länger als eine Wahlperiode.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=198', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9821, 36, 16, null, 'Autofreie Innenstädte mit Ausnahmen für Menschen mit besonderen Bedarfen und Lieferverkehr', '{3604,3603}', null, 2, 1, null, 'Autofreie Zonen bringen meist mehr Passanten und Aufenthalt, können aber Kunden aus dem Umland verlieren. Verkehrsplanung liegt bei den Kommunen, der Bund kann nur Rahmen setzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', 'https://trid.trb.org/View/408042', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9822, 36, 16, null, 'Leerstehende Gewerbeflächen wie Shoppingmalls oder Warenhäuser in kommunale oder genossenschaftliche Hand überführen und zu Sorgezentren umgestalten', '{3602}', 9757, 1, 2, null, 'Ein Fonds kann Kommunen den Zugriff auf Leerstand ermöglichen; Kultur- oder Sorgenutzungen beleben Zentren, schaffen aber kaum Einkaufsangebote, Wirkung kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9823, 36, 16, 'BE', 'Keine neuen Shopping-Center mehr genehmigen, um die Verdrängung von Kleingewerbe zu stoppen', '{3602}', 9770, 2, 2, null, 'In Großbritannien lenkten Bauhürden für Großflächen am Stadtrand Ketten in die Zentren, schwächten dort aber unabhängige Läden. Landes- und Regionalplanung kann steuern, ein pauschales Verbot ist rechtlich angreifbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=50', 'https://nber.org/papers/w19797', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9824, 36, 16, 'BE', 'Am Alexanderplatz einen Nutzungsmix vor allem mit Kultur und eine ansprechende Gestaltung ermöglichen', '{3602,3603}', 9765, 2, 2, null, 'Fallstudien zeigen nach Aufwertungen mehr Aufenthalt und höhere Ladenmieten; kausale Studien sind selten, höhere Mieten können kleine Geschäfte belasten. Umsetzung über Kommunen und Förderung in mehreren Jahren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=47', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9825, 36, 16, 'BE', 'Berliner Mitte als nichtkommerziellen öffentlichen Raum weiterentwickeln, klimaresiliente Umgestaltung des Rathausforums fertigstellen', '{3603}', 9765, 2, 2, null, 'Fallstudien zeigen nach Aufwertungen mehr Aufenthalt und höhere Ladenmieten; kausale Studien sind selten, höhere Mieten können kleine Geschäfte belasten. Umsetzung über Kommunen und Förderung in mehreren Jahren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=47', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9826, 36, 16, 'BE', 'Warenhaus-Standorte am Hermannplatz und Ku''damm erhalten statt Abriss, behutsam mit Anwohnern und Gewerbetreibenden weiterentwickeln', '{3602}', null, 1, 2, null, 'Erhalt großer Warenhäuser sichert Ankerangebote einzelner Zentren; ob der Betrieb weiterläuft, entscheidet der Betreiber, das Land kann nur über Planungsrecht Einfluss nehmen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=48', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9827, 36, 16, 'BE', 'Fahr- und Stellflächen für Autos besonders in Einkaufsstraßen reduzieren, um mehr Platz und Aufenthaltsqualität für Fußgänger zu schaffen', '{3603,3604}', 9763, 2, 2, null, 'Übersichten aus Deutschland und Großbritannien zeigen meist mehr Passanten und Umsatz in beruhigten Zonen, mit Einbußen in der Übergangszeit und am Rand; Zufahrtsbeschränkungen können Kunden aus dem Umland verdrängen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=66', 'https://trid.trb.org/View/408042', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9828, 36, 16, 'BE', 'Keine Lockerung des Sonntagsöffnungsverbots im Einzelhandel, Zahl der verkaufsoffenen Sonntage verringern', '{3604}', null, 0, 3, null, 'Weniger verkaufsoffene Sonntage schützen Beschäftigte, verbessern aber die Öffnungszeiten für Kunden nicht; Studien zur Sonntagsöffnung sprechen eher für leicht positive Effekte einer Lockerung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=95', 'https://researchonline.lse.ac.uk/id/eprint/61156/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9829, 36, 16, 'BE', 'Über den Bundesrat eine dauerhafte gesetzliche Begrenzung der Gewerbemieten vorschlagen, gegen Verdrängung von Läden und Einzelhandel', '{3602}', 9768, 1, 1, null, 'Mietbegrenzung oder Milieuschutz für Gewerbe kann kleine Läden in teuren Lagen halten; Schließungen haben aber meist andere Gründe, Datenbasis und Folgen sind ungeklärt. Das Land braucht eine Bundesmehrheit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=89', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9830, 36, 16, 'BE', 'Verbot von Leerstand auch bei Gewerbeimmobilien, um Spekulation zu unterbinden', '{3602}', 9758, 1, 1, null, 'Erfahrungen mit der französischen Leerstandsabgabe: in gefragten Lagen bringt sie Eigentümer zum Gespräch, in schwachen Lagen kaum Wirkung. Landesrechtliche Grundlage und Eigentumsschutz sind ungeklärt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=89', 'https://www.banquedesterritoires.fr/taxe-sur-les-friches-commerciales-un-outil-utiliser-bon-escient', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9831, 36, 16, 'BE', 'Leer gefallene Shoppingcenter in öffentliche Hand überführen und als gemeinschaftlich betriebene Sorgezentren im Quartier nutzen', '{3602}', 9756, 1, 2, null, 'Öffentliches Eigentum erlaubt gezielte Belegung leerer Flächen; Erwerb ist teuer, Vorkaufsrechte sind rechtlich eng, und Gemeinwohlnutzungen schaffen nicht unbedingt Einkaufsangebote.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=43', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9832, 36, 16, 'ST', 'Neues Stadtumbauprogramm bis 2035 gegen Leerstand finanzieren, für Rückbau und Aufwertung im Bestand (Abschnitt beginnt mit der Verödung der Innenstädte)', '{3602,3603}', 9766, 2, 2, null, 'Zentrenprogramme finanzieren Aufwertung, Geschäftsstraßenmanagement und Leerstandsprojekte, Begleitforschung berichtet verbesserte Perspektiven; kausale Wirkungen sind methodisch kaum nachweisbar. Ausbau hängt teils vom Bund ab.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=85', 'https://repos.hcu-hamburg.de/handle/hcu/503', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9833, 36, 17, 'MV', 'Aktive Standort- und Innenstadtpolitik, die inhabergeführte Geschäfte stärkt, Leerstand verringert und kleinteilige Versorgungsstrukturen in Innenstädten und Ortskernen erhält', '{3602}', 9752, 1, 3, null, 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=33', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9834, 36, 17, 'ST', 'Ausreichende Mittel für attraktive Innenstädte bereitstellen, im Zusammenhang mit gepflegten, gut gestalteten öffentlichen Räumen', '{3603}', null, 1, 2, null, 'Mehr Geld für attraktive Innenstädte kann Gestaltung und Pflege öffentlicher Räume verbessern; ohne Betrag, Programm oder Verwendungszweck bleibt die Wirkung unbestimmt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9835, 36, 17, 'ST', 'Kommunale Vorkaufsrechte konsequent gegen Leerstand und Spekulation nutzen, im Rahmen ganzheitlicher Gemeindeentwicklung', '{3602}', 9756, 1, 2, null, 'Öffentliches Eigentum erlaubt gezielte Belegung leerer Flächen; Erwerb ist teuer, Vorkaufsrechte sind rechtlich eng, und Gemeinwohlnutzungen schaffen nicht unbedingt Einkaufsangebote.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=34', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9836, 36, 18, null, 'Leerstehende Gewerbegebäude unbürokratisch zu Wohnraum umwandeln; aktives Leerstandsmanagement', '{3602}', null, 1, 3, null, 'Umwandlung leerer Gewerbeflächen in Wohnungen füllt Leerstand und bringt Bewohner in Zentren; Einkaufsflächen gehen dabei verloren. Der Bund hat Umnutzungen im Baurecht bereits erleichtert.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=94', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9837, 36, 18, null, 'Fonds, mit dem Kommunen Leerstand für kulturelle Projekte zurückkaufen können', '{3602}', 9757, 1, 2, null, 'Ein Fonds kann Kommunen den Zugriff auf Leerstand ermöglichen; Kultur- oder Sorgenutzungen beleben Zentren, schaffen aber kaum Einkaufsangebote, Wirkung kaum untersucht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=158', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9838, 36, 18, 'BE', 'Leerstehende Immobilien und alte Fabrikhallen in jedem Bezirk zu lokalen Gründer- und Nachbarschaftszentren (KiezLabs) umbauen, um Nebenstraßen und den stationären Einzelhandel zu beleben', '{3602}', 9755, 2, 2, null, 'Dauerhafte Mischnutzung (Kultur, Bildung, Gründer, Dienste) bringt Besuchsanlässe in Zentren zurück; Wirkung auf den verbleibenden Handel ist kaum belegt, Umbau ist teuer und dauert.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=61', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9839, 36, 18, 'BE', 'Alle leerstehenden Gewerbeflächen digital kartieren, damit Bezirke, Eigentümer und mögliche Nutzer wissen, was wo verfügbar ist', '{3602}', 9753, 1, 3, null, 'Ein Kataster schafft Transparenz und erleichtert Vermittlung an Nutzer; es ändert aber weder Nachfrage noch Mieten und wirkt nur zusammen mit weiteren Instrumenten.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=61', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9840, 36, 18, 'BE', 'Gegen Leerstand Nutzungsänderungen vereinfachen und Auflagen für Zwischennutzungen (Atelier, Sportstudio, Repair-Café) deutlich senken', '{3602}', 9754, 1, 3, null, 'Zwischennutzungen beleben leere Läden kurzfristig und mit wenig Risiko; sie sind befristet, oft ohne Handel, und ob sie zu dauerhafter Vermietung führen, ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=61', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9841, 36, 18, 'BE', 'Vergünstigte Nachfolgekredite über die Landesförderbank, damit Betriebsübernahmen etwa im Einzelhandel nicht an fehlenden Sicherheiten scheitern', '{3602}', 9769, 1, 3, null, 'Erleichterte Übernahmen können einzelne Schließungen verhindern; fehlende Nachfolge ist aber nur ein Grund für Leerstand neben Nachfrage und Onlinehandel, die Wirkung ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=62', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9842, 36, 18, 'BE', 'Genehmigungsverfahren bei Betriebsübernahmen vereinfachen, damit Betriebe etwa im Einzelhandel nicht schließen', '{3602}', 9769, 1, 3, null, 'Erleichterte Übernahmen können einzelne Schließungen verhindern; fehlende Nachfolge ist aber nur ein Grund für Leerstand neben Nachfrage und Onlinehandel, die Wirkung ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=62', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9843, 36, 18, 'BE', 'Parkplatzflächen schrittweise zurückbauen zugunsten breiter Gehwege, Radspuren, Grünflächen und Außengastronomie (Flaniermeilen für das lokale Gewerbe)', '{3603,3604}', 9763, 2, 2, null, 'Übersichten aus Deutschland und Großbritannien zeigen meist mehr Passanten und Umsatz in beruhigten Zonen, mit Einbußen in der Übergangszeit und am Rand; Zufahrtsbeschränkungen können Kunden aus dem Umland verdrängen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=35', 'https://trid.trb.org/View/408042', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9844, 36, 18, 'BE', 'Auf Bundesebene Tempo 30 als Regelgeschwindigkeit in Innenstädten anstreben, auch um die Aufenthaltsqualität zu erhöhen', '{3603}', null, 1, 1, null, 'Tempo 30 senkt Lärm und Unfälle und kann den Aufenthalt angenehmer machen; auf Angebot und Leerstand wirkt es kaum. Die Regelgeschwindigkeit legt der Bund fest, das Land kann nur werben.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=33', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9845, 36, 18, 'BE', 'Park-and-Ride-Standorte an Stadtgrenzen und in Außenbezirken, die die Innenstadt vom Verkehr entlasten und den Umstieg auf Bus und Bahn erleichtern', '{3604}', 9764, 1, 2, null, 'Erleichtert Besuchern aus dem Umland die Anreise und entlastet die Innenstadt; Park-and-Ride deckt seine Kosten meist nicht, ein kostenloses Ticket erhöht den Zuschussbedarf, die Wirkung auf den Handel ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=31', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9846, 36, 18, 'ST', 'Gegen an Attraktivität verlierende Ortskerne Stadtteilzentren stärken, „Dritte Orte“ schaffen und gemischte Quartiere fördern', '{3602}', 9752, 1, 3, null, 'Abstimmung von Land, Kommunen und Handel kann Maßnahmen bündeln; ohne benanntes Instrument, Mittel oder Ziel ist eine spürbare Wirkung auf Angebot und Leerstand aber kaum zu erwarten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=82', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9847, 36, 18, 'ST', 'Verkehrsberuhigung in Innenstädten durch Umgestaltung der Straßenräume zugunsten von Fuß- und Radverkehr', '{3603,3604}', 9763, 2, 2, null, 'Übersichten aus Deutschland und Großbritannien zeigen meist mehr Passanten und Umsatz in beruhigten Zonen, mit Einbußen in der Übergangszeit und am Rand; Zufahrtsbeschränkungen können Kunden aus dem Umland verdrängen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=89', 'https://trid.trb.org/View/408042', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9848, 36, 18, 'ST', 'Öffentlichen Raum klimaangepasst umgestalten und dabei Flächen in Ortskernen und auf Plätzen entsiegeln', '{3603}', 9765, 2, 2, null, 'Fallstudien zeigen nach Aufwertungen mehr Aufenthalt und höhere Ladenmieten; kausale Studien sind selten, höhere Mieten können kleine Geschäfte belasten. Umsetzung über Kommunen und Förderung in mehreren Jahren.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=179', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9849, 36, 18, 'ST', 'Bevorzugte Parkplätze in Innenstädten für geteilte Fahrzeuge und registrierte Fahrgemeinschaften', '{3604}', null, 1, 3, null, 'Bevorzugte Stellplätze für Carsharing und Fahrgemeinschaften sind leicht umsetzbar; sie verschieben Parkraum eher, als die Erreichbarkeit insgesamt zu verbessern.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=94', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9850, 36, 18, 'ST', 'Kostenlose Park-and-Ride-Parkplätze mit inbegriffenem Nahverkehrsticket in die Stadtzentren', '{3604}', 9764, 1, 2, null, 'Erleichtert Besuchern aus dem Umland die Anreise und entlastet die Innenstadt; Park-and-Ride deckt seine Kosten meist nicht, ein kostenloses Ticket erhöht den Zuschussbedarf, die Wirkung auf den Handel ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=94', null, 'offen', '2026-10-08', false, true, 'blind');

select setval(pg_get_serial_sequence('public.massnahmen', 'id'), (select max(id) from public.massnahmen));

